import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Satu gambar butuh satu menit untuk dikompres. Lima puluh gambar butuh waktu seharian, kecuali Anda mem-batch-nya.</p>\n<p>Kompresi batch memproses seluruh folder sekaligus. Anda memilih preset, melihat bilah progres, dan mengunduh semuanya bersamaan sebagai ZIP.</p>\n<p>Panduan ini membahas seluruh alur kerja, dari mengumpulkan file sampai memeriksa ZIP yang sudah selesai.</p>\n<h2 id=\"what-you-need\">Apa yang Anda Butuhkan Sebelum Memulai</h2>\n<p>Kumpulkan gambar original dalam satu folder. Bekerja dari original memberi kualitas terbaik; bekerja dari salinan hasil kompres menambah kerusakan.</p>\n<p>Tentukan untuk apa gambar itu. Thumbnail butuh preset File Lebih Kecil, sedangkan foto portofolio butuh Kualitas Tinggi.</p>\n<p>Periksa berapa banyak gambar yang Anda punya. Batch berisi dua puluh berjalan cepat di mana pun, sedangkan batch berisi dua ratus mungkin perlu dibagi di ponsel.</p>\n<p>Pastikan Anda punya cukup ruang kosong. Unduhan ZIP butuh ruang di perangkat Anda, kira-kira sebesar ukuran batch hasil kompres.</p>\n<h2 id=\"step-1-open\">Langkah 1: Buka Alat Kompres Massal</h2>\n<p>Buka <a href=\"/id/kompres-gambar-secara-massal/\">alat kompres gambar massal</a> di browser Anda. Tidak butuh akun atau pemasangan apa pun.</p>\n<p>Alat berjalan sepenuhnya di perangkat Anda. Foto Anda diproses secara lokal dan tidak pernah diunggah ke server.</p>\n<p>Jika Anda memakai laptop, halaman ini bekerja paling baik dengan seret dan letakkan. Di ponsel, tombol unggah membuka galeri Anda.</p>\n<p>Tandai halaman itu bila Anda sering mengompres batch. Ini rute tercepat menuju pustaka foto yang lebih kecil.</p>\n<h2 id=\"step-2-add-files\">Langkah 2: Tambahkan Gambar Anda</h2>\n<p>Seret gambar Anda ke area unggah, atau ketuk untuk menjelajah dan memilihnya. Anda bisa menambahkan seluruh folder sekaligus di kebanyakan browser.</p>\n<p>File JPG, PNG, WebP, dan HEIC diterima. Batch campuran bisa dipakai, jadi foto dan tangkapan layar bisa berbagi satu batch.</p>\n<p>Periksa antrean setelah menambahkan file. Setiap gambar seharusnya muncul dengan nama dan ukurannya, sehingga file yang hilang mudah dikenali.</p>\n<p>Tambahkan lagi file nanti jika ada yang terlupa. Antrean menerima gambar baru bahkan setelah batch pertama selesai.</p>\n<h2 id=\"step-3-preset\">Langkah 3: Pilih Preset</h2>\n<p>Pilih Seimbang untuk kebanyakan pekerjaan. Ia memulai di kualitas 70 persen dan memberi jalan tengah yang bagus antara ukuran dan tampilan.</p>\n<p>Pilih File Lebih Kecil untuk thumbnail, avatar, dan gambar yang akan ditampilkan kecil. Kompresi ekstra tidak terlihat pada ukuran tampilan yang kecil.</p>\n<p>Pilih Kualitas Tinggi untuk portofolio, galeri, dan gambar pajangan. File tetap lebih besar, tetapi detailnya sepadan.</p>\n<p>Preset menetapkan titik awal. Setiap gambar tetap dioptimalkan secara individual, jadi potret sederhana dan lanskap detail mendapat perlakuan berbeda.</p>\n<h2 id=\"step-4-run\">Langkah 4: Jalankan Batch</h2>\n<p>Mulai batch dan perhatikan bilah progres. Ia menunjukkan file mana yang selesai dan berapa banyak total ukuran yang sudah dihemat sejauh ini.</p>\n<p>Pemrosesan terjadi satu gambar demi satu. Itu menjaga browser tetap responsif, bukan membeku saat bekerja.</p>\n<p>Jangan tutup tab saat batch berjalan. Pekerjaan terjadi di browser Anda, jadi menutup halaman menghentikan kompresi.</p>\n<p>Batch besar butuh beberapa menit. Gunakan waktu itu untuk menyiapkan folder tujuan atau menulis artikel blog yang menjadi milik gambar itu.</p>\n<h2 id=\"step-5-preview\">Langkah 5: Lihat Pratinjau Hasil Perorangan</h2>\n<p>Ketika batch selesai, lihat pratinjau hasilnya sebelum mengunduh. Klik gambar apa pun untuk melihatnya pada ukuran penuh.</p>\n<p>Periksa dulu gambar yang paling sulit. Foto detail atau tangkapan layar dengan teks kecil akan menunjukkan masalah sebelum potret sederhana.</p>\n<p>Bandingkan beberapa hasil dengan originalnya. Perbedaan kecil itu normal; teks yang tidak terbaca atau kulit yang bercak bukan.</p>\n<p>Jika satu gambar tampak buruk, kompres ulang sendirian dengan pengaturan berbeda. Anda tidak perlu menjalankan ulang seluruh batch untuk satu file.</p>\n<h2 id=\"step-6-download-zip\">Langkah 6: Unduh ZIP</h2>\n<p>Klik Unduh Semua untuk mendapatkan satu file ZIP berisi setiap gambar hasil kompres di dalamnya. ZIP menjaga kumpulan tetap teratur dalam satu paket.</p>\n<p>Ekstrak ZIP ke foldernya sendiri. Itu menjaga kumpulan hasil kompres tetap terpisah dari original dan mudah ditemukan nanti.</p>\n<p>Periksa file hasil ekstrak. Buka beberapa pada ukuran penuh dan pastikan tampak benar sebelum mengunggahnya ke mana pun.</p>\n<p>Ganti nama file dengan jelas jika nama otomatisnya kurang deskriptif. Nama yang jelas menghemat kebingungan ketika kumpulan itu besar.</p>\n<h2 id=\"fixing-problems\">Memperbaiki Masalah dalam Batch</h2>\n<p>Jika satu gambar membesar, biarkan apa adanya. Alat memperingatkan Anda ketika pengodean ulang membuat file lebih besar, dan original adalah file yang lebih baik.</p>\n<p>Jika gambar tampak buram, sumbernya mungkin sudah terlalu kecil. Kompres ulang satu file itu dari original yang lebih besar dengan preset Kualitas Tinggi.</p>\n<p>Jika warnanya tampak salah, periksa transparansinya. Mengubah PNG transparan menjadi JPG akan mengisi latarnya, biasanya dengan warna putih.</p>\n<p>Jika batch lambat, bagi menjadi kelompok yang lebih kecil. Ponsel terutama diuntungkan batch berisi dua puluh, bukan dua ratus.</p>\n<h2 id=\"blog-workflow\">Alur Kerja: Satu Set Thumbnail Blog</h2>\n<p>Kumpulkan thumbnail untuk sekumpulan artikel dan unggah sebagai satu batch. Pilih preset Seimbang untuk hasil yang konsisten.</p>\n<p>Lihat pratinjau tiga atau empat hasil, bukan hanya yang pertama. Satu thumbnail buruk bisa bersembunyi di antara yang bagus.</p>\n<p>Unduh ZIP, ekstrak, dan unggah file ke blog Anda. Simpan original untuk jaga-jaga bila artikel butuh gambar yang lebih besar nanti.</p>\n<p>Periksa artikel yang diterbitkan di ponsel dan laptop. Thumbnail harus termuat cepat dan tampak tajam di keduanya.</p>\n<h2 id=\"shop-workflow\">Alur Kerja: Katalog Produk</h2>\n<p>Kumpulkan foto produk untuk peluncuran dan unggah sebagai satu batch. Gunakan preset Kualitas Tinggi supaya produk tampak terbaik.</p>\n<p>Lihat pratinjau produk yang paling detail dulu. Tekstur kain dan label cetak adalah hal pertama yang melembut.</p>\n<p>Unduh ZIP dan unggah gambar ke toko. Periksa beberapa halaman produk untuk memastikan gambar tampil dengan benar.</p>\n<p>Simpan original di drive bersama. Ketika musim berikutnya diluncurkan, tim bisa mengompres baru dari master.</p>\n<h2 id=\"album-workflow\">Alur Kerja: Album Foto Bersama</h2>\n<p>Kumpulkan foto untuk album dan unggah sebagai satu batch. Preset Seimbang menjaga album tetap ringan tanpa merusak kenangan.</p>\n<p>Lihat pratinjau beberapa foto favorit sebelum mengunduh. Foto yang dicintai pantas mendapat pemeriksaan teliti, bahkan dalam batch berisi seratus.</p>\n<p>Unduh ZIP dan bagikan kepada keluarga atau teman. Album hasil kompres terunduh cepat, bahkan pada koneksi yang lambat.</p>\n<p>Simpan original dengan aman. Salinan yang dibagikan bisa dibuang, dan original adalah yang Anda inginkan dalam sepuluh tahun.</p>\n<h2 id=\"folder-selection\">Memilih Seluruh Folder Sekaligus</h2>\n<p>Kebanyakan browser desktop memungkinkan Anda memilih seluruh folder, bukan hanya file perorangan. Itu cara tercepat untuk memulai batch.</p>\n<p>Carilah opsi folder di pemilih file. Ia muncul sebagai pilihan terpisah di Chrome, Edge, dan Firefox pada desktop.</p>\n<p>Periksa antrean setelah memilih folder. Subfolder bisa disertakan atau diabaikan tergantung browser, jadi pastikan jumlahnya cocok.</p>\n<p>Hapus file apa pun yang tidak termasuk. Folder sering berisi tangkapan layar yang tersasar atau file lama yang tidak seharusnya dikompres.</p>\n<p>Di ponsel, pemilihan folder terbatas. Pilih file berkelompok dari galeri, dan pertahankan setiap kelompok sekitar dua puluh gambar.</p>\n<h2 id=\"progress-bar\">Membaca Bilah Progres</h2>\n<p>Bilah progres menunjukkan seberapa jauh batch berjalan dan berapa banyak ukuran yang sudah dihemat sejauh ini. Ia diperbarui saat setiap gambar selesai.</p>\n<p>Laju yang stabil berarti batch sehat. Jika bilah berhenti pada satu file, file itu mungkin luar biasa besar atau rumit.</p>\n<p>Jangan tutup tab saat bilah bergerak. Pekerjaan terjadi di browser Anda, dan menutup halaman menghentikan batch.</p>\n<p>Jika tab browser tertidur di latar belakang, batch bisa berhenti sejenak. Biarkan tab tetap terlihat sampai batch selesai.</p>\n<p>Untuk batch yang sangat besar, bilah itu sahabat terbaik Anda. Ia mengubah penantian panjang menjadi progres yang terlihat, file demi file.</p>\n<h2 id=\"per-file-results\">Memahami Hasil Per File</h2>\n<p>Setiap file yang selesai menunjukkan hasilnya sendiri: ukuran original, ukuran hasil kompres, dan persentase yang dihemat. Angkanya sangat bervariasi di seluruh batch.</p>\n<p>Potret sederhana sering menghemat 90 persen atau lebih. Lanskap detail mungkin hanya menghemat 70 persen, karena mereka punya lebih banyak data yang layak disimpan.</p>\n<p>File yang hampir tidak menghemat apa pun mungkin sudah terkompres sebelumnya. Alat sudah berusaha sebaik mungkin, tetapi hanya sedikit yang tersisa untuk dibuang.</p>\n<p>File yang membesar adalah peringatan, bukan kegagalan. Simpan original untuk file itu dan lanjutkan dengan sisa batch.</p>\n<p>Urutkan hasil berdasarkan penghematan bila Anda bisa. Penghemat terkecil adalah file yang paling mungkin butuh perhatian perorangan.</p>\n<h2 id=\"retrying-failed\">Mencoba Ulang File yang Gagal atau Buruk</h2>\n<p>Sebagian file gagal atau keluar buruk dalam batch. Itu normal, dan perbaikannya adalah menanganinya secara individual.</p>\n<p>Tarik file bermasalah keluar dari kumpulan. Kompres sendirian dengan preset Kualitas Tinggi dan lihat pratinjau hasilnya dengan teliti.</p>\n<p>Jika formatnya masalah, ubah. Foto PNG yang dikompres ulang sebagai JPG sering berubah dari kegagalan menjadi hasil yang bersih.</p>\n<p>Jika sumbernya masalah, carilah original yang lebih baik. File yang sudah terkompres tidak bisa diselamatkan pengaturan apa pun.</p>\n<p>Ganti file buruk dalam kumpulan akhir. Batch tetap utuh, dan hanya file bermasalah yang berubah.</p>\n<h2 id=\"uploading-after-batch\">Mengunggah Hasil Batch</h2>\n<p>Setelah diekstrak, unggah file ke tujuannya berkelompok. Mengunggah lima puluh file sekaligus bisa membebani sebagian platform.</p>\n<p>Periksa beberapa unggahan pertama dengan teliti. Pastikan tampilannya benar sebelum mengunggah sisa kumpulan.</p>\n<p>Samakan nama file dengan tujuannya. Gambar produk yang diunggah ke halaman produk yang salah adalah kesalahan memalukan yang bisa dihindari.</p>\n<p>Simpan ZIP sampai unggahannya terkonfirmasi. Jika unggahan gagal, ZIP sudah punya file yang siap tanpa pengulangan.</p>\n<p>Hapus salinan hasil kompres lokal hanya setelah unggahannya terverifikasi. Original tetap aman apa pun yang terjadi.</p>\n<p>Bagi batch besar berdasarkan jenis gambar, bukan hanya berdasarkan jumlah. Foto produk, tangkapan layar, dan foto acara punya kebutuhan yang berbeda, dan preset yang sama tidak selalu cocok untuk ketiganya. Dua batch yang fokus selalu memberi hasil lebih baik daripada satu batch besar yang mencampur semuanya.</p>\n<p>Siapkan folder tujuan sebelum menjalankan batch, supaya hasil ekstrak ZIP langsung punya tempat. Folder bernama sesuai proyek dan tanggal, misalnya katalog-mei-2026, membuat file mudah ditemukan berbulan-bulan kemudian. Jangan biarkan hasil batch menumpuk di folder unduhan, karena di sanalah file paling mudah hilang atau tertukar.</p>\n<p>Periksa jumlah file hasil ekstrak dengan jumlah file original sebelum mengunggah apa pun, karena satu file yang hilang sekarang lebih mudah diperbaiki daripada gambar yang hilang di halaman tayang.</p>\n<h2 id=\"time-estimates\">Berapa Lama Batch Berlangsung?</h2>\n<p>Batch berisi dua puluh foto ponsel butuh sekitar satu menit di laptop modern. Batch yang sama bisa butuh tiga menit di ponsel.</p>\n<p>File yang lebih besar butuh waktu lebih lama. Batch berisi foto kamera 10MB butuh waktu pemrosesan lebih lama per file daripada batch berisi foto ponsel 2MB.</p>\n<p>Preset juga memengaruhi kecepatan. Kualitas Tinggi menjalankan lebih banyak putaran optimasi daripada File Lebih Kecil, jadi sedikit lebih lambat.</p>\n<p>Rencanakan penantiannya. Mulai batch, lalu gunakan waktu itu untuk menulis artikel, menyiapkan deskripsi produk, atau menata folder tujuan.</p>\n<p>Untuk batch yang sangat besar, jalankan saat Anda tidak butuh komputer untuk pekerjaan berat lain. Kompresi memakai prosesor, dan multitasking memperlambatnya.</p>\n<h2 id=\"sharing-zip\">Berbagi ZIP dengan Orang Lain</h2>\n<p>File ZIP adalah cara termudah untuk membagikan kumpulan hasil kompres. Satu file membawa setiap gambar, siap diekstrak dan dipakai.</p>\n<p>Kirim ZIP lewat email ketika ukurannya cukup kecil. Kebanyakan sistem email menerima lampiran sampai 20MB atau 25MB.</p>\n<p>Untuk ZIP yang lebih besar, gunakan tautan berbagi file. Unggah ZIP ke drive dan bagikan tautannya, bukan filenya sendiri.</p>\n<p>Beri tahu penerima apa isinya. Catatan singkat tentang preset dan tujuannya mencegah kebingungan di pihak mereka.</p>\n<p>Simpan salinan ZIP untuk diri Anda sendiri. Jika penerima kehilangannya, Anda bisa mengirim ulang tanpa menjalankan ulang batch.</p>\n<h2 id=\"cleanup-after\">Membersihkan Setelah Batch</h2>\n<p>Setelah batch diunggah dan terverifikasi, bersihkan file kerja. Ruang kerja yang rapi mencegah tertukar di batch berikutnya.</p>\n<p>Hapus salinan hasil kompres yang sudah diekstrak begitu mereka aman terunggah. ZIP tetap sebagai cadangan kumpulan itu.</p>\n<p>Simpan original selamanya. Mereka tinggal di foldernya sendiri, terpisah dari setiap salinan hasil kompres.</p>\n<p>Arsipkan ZIP bersama proyek yang dimilikinya. ZIP yang disimpan bersama artikel blog atau peluncuran produk bisa ditemukan nanti.</p>\n<p>Ruang kerja yang bersih adalah ruang kerja yang cepat. Lima menit bersih-bersih sekarang menghemat satu jam pencarian nanti.</p>\n<p>Katalog toko daring adalah batch yang paling sering diulang. Foto produk baru datang setiap minggu, dan batch yang sama menjaga toko tetap konsisten.</p>\n<p>Bagi batch katalog berdasarkan kategori, bukan berdasarkan tanggal. Kategori seperti pakaian, aksesori, dan peralatan rumah tangga masing-masing punya kebutuhan yang berbeda.</p>\n<p>Beri nama file berdasarkan SKU produk. Nama SKU membuat foto mudah dicocokkan dengan daftar produk, bahkan ketika katalog berisi ratusan item.</p>\n<p>Periksa halaman toko setelah batch diunggah. Foto yang salah tempat di halaman produk adalah kesalahan yang mudah dikenali dan cepat diperbaiki.</p>\n<h2 id=\"final-check\">Pemeriksaan Terakhir Sebelum Mengunggah</h2>\n<p>Buka tiga gambar acak dari batch yang sudah selesai pada ukuran penuh. Jika tampak bersih, batch itu bagus; jika satu tampak lembut, periksa sisanya sebelum mengunggah.</p>\n<p>Pastikan ZIP terekstrak dengan benar dan jumlah file cocok dengan batch aslinya. File yang hilang sekarang lebih mudah diperbaiki daripada gambar yang hilang di halaman yang sudah tayang.</p>\n<p>Untuk panduan lengkap kompresi massal, baca <a href=\"/id/blog/kompres-gambar-massal-panduan-lengkap/\">Kompres Gambar Massal: Panduan Lengkap</a>. Untuk praktik terbaik batch, lihat <a href=\"/id/blog/kompres-gambar-massal-tips-dan-praktik-terbaik/\">Kompresi Gambar Massal: Alur ZIP dan Praktik Terbaik</a>. Jika Anda butuh ukuran file yang persis, <a href=\"/id/kompres-gambar-ke-ukuran-target/\">alat kompres ke ukuran file target</a> menerima angka apa pun yang Anda ketik.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Bagaimana cara mengompres seluruh folder gambar sekaligus?","answer":"Buka alat kompres massal dan seret folder ke area unggah, atau pilih semua file sekaligus. Pilih preset, jalankan batch, dan unduh hasilnya sebagai satu ZIP. Setiap gambar dikompres secara individual untuk kualitas terbaik."},{"question":"Preset mana yang harus saya pakai untuk thumbnail blog?","answer":"Seimbang bekerja dengan baik untuk kebanyakan thumbnail, memulai di kualitas 70 persen. Gunakan File Lebih Kecil jika thumbnail ditampilkan sangat kecil, dan Kualitas Tinggi jika mereka gambar fitur yang besar. Lihat pratinjau beberapa hasil sebelum mengunduh seluruh batch."},{"question":"Bisakah saya mengompres gambar di ponsel secara massal?","answer":"Bisa, alat bekerja di browser ponsel. Pertahankan batch lebih kecil di ponsel, sekitar dua puluh gambar sekaligus, karena ponsel punya memori yang lebih sedikit. Unduh ZIP ke aplikasi Files Anda dan ekstrak di sana."},{"question":"Apa yang terjadi jika ponsel saya kehabisan memori selama batch?","answer":"Batch bisa melambat atau berhenti. Bagi gambar yang tersisa menjadi kelompok yang lebih kecil dan jalankan secara terpisah. Browser desktop menangani batch yang lebih besar dengan lebih nyaman, jadi gunakan laptop untuk pekerjaan yang sangat besar."},{"question":"Apakah saya perlu mengubah ukuran gambar sebelum kompresi massal?","answer":"Tidak, alat kompres massal mempertahankan dimensi piksel original dan hanya mengurangi ukuran file. Jika Anda juga butuh dimensi yang lebih kecil, ubah dulu ukuran gambar dengan alat pengubah ukuran, lalu kompres file hasil ubahan itu dalam satu batch."},{"question":"Bagaimana saya tahu batch benar-benar menghemat ruang?","answer":"Ringkasan batch melaporkan total ukuran sebelum dan sesudah kompresi, ditambah persentase yang dihemat. Batch foto biasa turun 80 sampai 90 persen. Anda juga bisa membandingkan ukuran ZIP dengan ukuran folder original."}];
